  }
}

input.new_string:
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: var(--radius);
  --radius-xl: 0.875rem;
  --radius-2xl: 1.125rem;
  --radius-3xl: 1.5rem;
  --radius-4xl: 2rem;
  --shadow-xs: 0 1px 2px 0 rgb(16 24 40 / 0.04);
  --shadow-sm: 0 1px 3px 0 rgb(16 24 40 / 0.06), 0 1px 2px -1px rgb(16 24 40 / 0.04);
  --shadow-md: 0 4px 8px -2px rgb(16 24 40 / 0.06), 0 2px 4px -2px rgb(16 24 40 / 0.04);
  --shadow-lg: 0 12px 24px -6px rgb(16 24 40 / 0.08), 0 4px 8px -4px rgb(16 24 40 / 0.04);
  --shadow-xl: 0 24px 48px -12px rgb(16 24 40 / 0.12);
  --shadow-soft: 0 1px 3px 0 rgb(16 24 40 / 0.04), 0 1px 2px -1px rgb(16 24 40 / 0.03);
  --shadow-soft-md: 0 6px 16px -4px rgb(16 24 40 / 0.06), 0 2px 6px -2px rgb(16 24 40 / 0.04);
  --shadow-card: 0 1px 2px 0 rgb(16 24 40 / 0.04), 0 0 0 1px rgb(16 24 40 / 0.05);
  --tracking-tighter: -0.02em;
  --tracking-tight: -0.012em;
  --tracking-normal: 0em;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-base: 220ms;
  --animate-fade-in-up: fade-in-up 0.4s var(--ease-out-expo);
  --animate-scale-in: scale-in 0.22s var(--ease-out-expo);
  --animate-shimmer: shimmer 1.6s linear infinite;
  @keyframes fade-in-up {
    0% {
      opacity: 0;
      transform: translateY(8px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }
  @keyframes scale-in {
    0% {
      opacity: 0;
      transform: scale(0.96);
    }
    100% {
      opacity: 1;
      transform: scale(1);
    }
  }
  @keyframes shimmer {
    0% {
      background-position: -200% 0;
    }
    100% {
      background-position: 200% 0;
    }
  }
}

