import { Pencil, Archive, Inbox } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/common/empty-state";
import { StatusBadge } from "@/components/inbox/status-badge";
import { PriorityBadge } from "@/components/inbox/priority-badge";
import { SlaChip } from "@/components/inbox/sla-chip";
import { formatRelative } from "@/lib/utils/time";
import type { Request, Client, Assignee } from "@/lib/types";

interface InboxTableProps {
  requests: readonly Request[];
  clients: readonly Client[];
  assignees: readonly Assignee[];
  totalCount: number;
  onClearFilters?: () => void;
}

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((n) => n[0] ?? "")
    .slice(0, 2)
    .join("")
    .toUpperCase();
}


export function InboxTable({
  requests,
  clients,
  assignees,
  totalCount,
  onClearFilters,
}: InboxTableProps) {
  const clientMap = new Map(clients.map((c) => [c.id, c]));
  const assigneeMap = new Map(assignees.map((a) => [a.id, a]));

  return (
    <Card className="overflow-hidden">
      <CardContent className="p-0">
        {requests.length === 0 ? (
          <EmptyState
            icon={Inbox}
            title="No matching requests"
            description="Try clearing your filters to see all requests."
            action={{ label: "Clear filters", onClick: onClearFilters }}
          />
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="pl-4 min-w-[200px]">Title</TableHead>
                  <TableHead className="min-w-[140px]">Client</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="hidden md:table-cell">Priority</TableHead>
                  <TableHead className="hidden md:table-cell">Assignee</TableHead>
                  <TableHead>SLA</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead className="w-20 text-right pr-4">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {requests.map((req) => {
                  const client = clientMap.get(req.clientId);
                  const assignee = assigneeMap.get(req.assigneeId);

                  return (
                    <TableRow
                      key={req.id}
                      className="cursor-pointer hover:bg-muted/30"
                      onClick={() => {
                        /* TODO(phase2): navigate to request detail */
                      }}
                    >
                      {/* Title */}
                      <TableCell className="pl-4 font-medium max-w-[240px]">
                        <span className="truncate block">{req.title}</span>
                      </TableCell>

                      {/* Client */}
                      <TableCell>
                        {client ? (
                          <div className="flex items-center gap-2">
                            <Avatar size="sm">
                              <AvatarImage
                                src={client.avatarUrl}
                                alt={client.name}
                              />
                              <AvatarFallback>
                                {getInitials(client.name)}
                              </AvatarFallback>
                            </Avatar>
                            <span className="text-sm truncate max-w-[100px]">
                              {client.company}
                            </span>
                          </div>
                        ) : (
                          <span className="text-muted-foreground text-xs">—</span>
                        )}
                      </TableCell>

                      {/* Status */}
                      <TableCell>
                        <StatusBadge status={req.status} />
                      </TableCell>

                      {/* Priority — hidden on md and below */}
                      <TableCell className="hidden md:table-cell">
                        <PriorityBadge priority={req.priority} />
                      </TableCell>

                      {/* Assignee — hidden on md and below */}
                      <TableCell className="hidden md:table-cell">
                        {assignee ? (
                          <div className="flex items-center gap-2">
                            <Avatar size="sm">
                              <AvatarImage
                                src={assignee.avatarUrl}
                                alt={assignee.name}
                              />
                              <AvatarFallback>
                                {getInitials(assignee.name)}
                              </AvatarFallback>
                            </Avatar>
                            <span className="text-xs text-muted-foreground truncate max-w-[80px]">
                              {assignee.name.split(" ")[0]}
                            </span>
                          </div>
                        ) : (
                          <span className="text-muted-foreground text-xs">—</span>
                        )}
                      </TableCell>

                      {/* SLA */}
                      <TableCell>
                        <SlaChip slaDueAt={req.slaDueAt} />
                      </TableCell>

                      {/* Created */}
                      <TableCell className="text-muted-foreground text-xs">
                        {formatRelative(req.createdAt)}
                      </TableCell>

                      {/* Actions */}
                      <TableCell
                        className="text-right pr-4"
                        onClick={(e) => e.stopPropagation()}
                      >
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            className="size-7 p-0"
                            aria-label="Edit request"
                            onClick={(e) => {
                              e.stopPropagation();
                              /* TODO(phase2): open edit dialog */
                            }}
                          >
                            <Pencil className="size-3.5" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            className="size-7 p-0"
                            aria-label="Archive request"
                            onClick={(e) => {
                              e.stopPropagation();
                              /* TODO(phase2): archive request */
                            }}
                          >
                            <Archive className="size-3.5" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>

            {/* Footer */}
            <div className="px-4 py-3 border-t text-xs text-muted-foreground">
              Showing {requests.length} of {totalCount}
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

function Table({ className, ...props }: React.ComponentProps<"table">) {
  return (
    <div
      data-slot="table-container"
      className="relative w-full overflow-x-auto"
    >
      <table
        data-slot="table"
        className={cn("w-full caption-bottom text-sm", className)}
        {...props}
      />
    </div>
  )
}

function TableHeader({ className, ...props }: React.ComponentProps<"thead">) {
  return (
    <thead
      data-slot="table-header"
      className={cn("[&_tr]:border-b", className)}
      {...props}
    />
  )
}

function TableBody({ className, ...props }: React.ComponentProps<"tbody">) {
  return (
    <tbody
      data-slot="table-body"
      className={cn("[&_tr:last-child]:border-0", className)}
      {...props}
    />
  )
}

function TableFooter({ className, ...props }: React.ComponentProps<"tfoot">) {
  return (
    <tfoot
      data-slot="table-footer"
      className={cn(
        "border-t bg-muted/50 font-medium [&>tr]:last:border-b-0",
        className
      )}
      {...props}
    />
  )
}

function TableRow({ className, ...props }: React.ComponentProps<"tr">) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        "border-b transition-colors hover:bg-muted/50 has-aria-expanded:bg-muted/50 data-[state=selected]:bg-muted",
        className
      )}
      {...props}
    />
  )
}

function TableHead({ className, ...props }: React.ComponentProps<"th">) {
  return (
    <th
      data-slot="table-head"
      className={cn(
        "h-10 px-2 text-left align-middle font-medium whitespace-nowrap text-foreground [&:has([role=checkbox])]:pr-0",
        className
      )}
      {...props}
    />
  )
}

function TableCell({ className, ...props }: React.ComponentProps<"td">) {
  return (
    <td
      data-slot="table-cell"
      className={cn(
        "p-2 align-middle whitespace-nowrap [&:has([role=checkbox])]:pr-0",
        className
      )}
      {...props}
    />
  )
}

function TableCaption({
  className,
  ...props
}: React.ComponentProps<"caption">) {
  return (
    <caption
      data-slot="table-caption"
      className={cn("mt-4 text-sm text-muted-foreground", className)}
      {...props}
    />
  )
}

export {
  Table,
  TableHeader,
  TableBody,
  TableFooter,
  TableHead,
  TableRow,
  TableCell,
  TableCaption,
}

