import { Pencil, Trash2, Package } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/common/empty-state";
import type { Service, ServiceCategory } from "@/lib/types";

interface ServicesTableProps {
  services: readonly Service[];
  onClearFilters?: () => void;
}

const TOTAL_SERVICES = 6;

const categoryConfig: Record<
  ServiceCategory,
  { label: string; className: string }
> = {
  design: {
    label: "Design",
    className: "bg-violet-100 text-violet-700 ring-1 ring-violet-200",
  },
  development: {
    label: "Development",
    className: "bg-blue-100 text-blue-700 ring-1 ring-blue-200",
  },
  seo: {
    label: "SEO",
    className: "bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200",
  },
  content: {
    label: "Content",
    className: "bg-amber-100 text-amber-700 ring-1 ring-amber-200",
  },
  video: {
    label: "Video",
    className: "bg-rose-100 text-rose-700 ring-1 ring-rose-200",
  },
  ads: {
    label: "Ads",
    className: "bg-orange-100 text-orange-700 ring-1 ring-orange-200",
  },
};

const priceFormatter = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});

function CategoryBadge({ category }: { category: ServiceCategory }) {
  const config = categoryConfig[category];
  return (
    <span
      className={`inline-flex items-center rounded-full px-2 py-0.5 text-xs font-medium whitespace-nowrap ${config.className}`}
    >
      {config.label}
    </span>
  );
}

export function ServicesTable({
  services,
  onClearFilters,
}: ServicesTableProps) {
  return (
    <Card className="overflow-hidden">
      <CardContent className="p-0">
        {services.length === 0 ? (
          <EmptyState
            icon={Package}
            title="No matching services"
            description="Try clearing your filters to see all services."
            action={{ label: "Clear filters", onClick: onClearFilters }}
          />
        ) : (
          <>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="pl-4 min-w-[180px]">Service</TableHead>
                  <TableHead className="hidden md:table-cell min-w-[260px]">
                    Description
                  </TableHead>
                  <TableHead className="text-right">Price</TableHead>
                  <TableHead>Turnaround</TableHead>
                  <TableHead className="text-right">Active Clients</TableHead>
                  <TableHead className="w-20 text-right pr-4">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {services.map((service) => (
                  <TableRow
                    key={service.id}
                    className="cursor-pointer hover:bg-muted/30"
                    onClick={() => {
                      /* TODO(phase2): navigate to service detail */
                    }}
                  >
                    {/* Name + category chip */}
                    <TableCell className="pl-4">
                      <p className="font-medium text-sm leading-tight">
                        {service.name}
                      </p>
                      <div className="mt-1">
                        <CategoryBadge category={service.category} />
                      </div>
                    </TableCell>

                    {/* Description — hidden on md and below */}
                    <TableCell className="hidden md:table-cell">
                      <p className="text-xs text-muted-foreground line-clamp-2 max-w-md">
                        {service.description}
                      </p>
                    </TableCell>

                    {/* Flat Price */}
                    <TableCell className="text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <span className="font-semibold tabular-nums text-sm">
                          {priceFormatter.format(service.flatPrice)} / mo
                        </span>
                        <span className="inline-flex items-center rounded px-1 py-px text-[10px] font-semibold uppercase tracking-wide bg-primary/5 text-primary">
                          FLAT
                        </span>
                      </div>
                    </TableCell>

                    {/* Turnaround */}
                    <TableCell className="text-sm text-muted-foreground">
                      {service.turnaroundDays === 1
                        ? "1 day"
                        : `${service.turnaroundDays} days`}
                    </TableCell>

                    {/* Active Clients */}
                    <TableCell className="text-right tabular-nums text-sm">
                      {service.activeClients}
                    </TableCell>

                    {/* Actions */}
                    <TableCell
                      className="text-right pr-4"
                      onClick={(e) => e.stopPropagation()}
                    >
                      <div className="flex items-center justify-end gap-1">
                        <Button
                          variant="ghost"
                          size="sm"
                          className="size-7 p-0 text-muted-foreground"
                          aria-label="Edit service"
                          onClick={(e) => {
                            e.stopPropagation();
                            /* TODO(phase2): open edit dialog */
                          }}
                        >
                          <Pencil className="size-3.5" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="size-7 p-0 text-muted-foreground"
                          aria-label="Delete service"
                          onClick={(e) => {
                            e.stopPropagation();
                            /* TODO(phase2): confirm delete */
                          }}
                        >
                          <Trash2 className="size-3.5" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>

            {/* Footer */}
            <div className="px-4 py-3 border-t text-xs text-muted-foreground">
              {services.length === TOTAL_SERVICES
                ? `Showing all ${TOTAL_SERVICES} services`
                : `Showing ${services.length} of ${TOTAL_SERVICES}`}
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

