import { KanbanCard } from "@/components/inbox/kanban-card";
import type { Request, Client, Assignee, RequestStatus } from "@/lib/types";

interface InboxKanbanProps {
  requests: readonly Request[];
  clients: readonly Client[];
  assignees: readonly Assignee[];
}

const COLUMNS: readonly { id: RequestStatus; label: string }[] = [
  { id: "backlog", label: "Backlog" },
  { id: "in_progress", label: "In Progress" },
  { id: "review", label: "Review" },
  { id: "delivered", label: "Delivered" },
] as const;

export function InboxKanban({ requests, clients, assignees }: InboxKanbanProps) {
  const clientMap = new Map(clients.map((c) => [c.id, c]));
  const assigneeMap = new Map(assignees.map((a) => [a.id, a]));

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
      {COLUMNS.map((col) => {
        const colRequests = requests.filter((r) => r.status === col.id);

        return (
          <div key={col.id} className="rounded-xl bg-muted/30 p-3">
            {/* Column header */}
            <div className="flex items-center justify-between px-1 pb-3">
              <h3 className="text-sm font-semibold">{col.label}</h3>
              <span className="text-xs bg-muted rounded-full px-2 py-0.5">
                {colRequests.length}
              </span>
            </div>

            {/* Column body */}
            <div className="max-h-[calc(100vh-20rem)] overflow-y-auto space-y-2 pr-1">
              {colRequests.length === 0 ? (
                <p className="text-xs text-muted-foreground text-center py-4">
                  No requests
                </p>
              ) : (
                colRequests.map((req) => (
                  <KanbanCard
                    key={req.id}
                    request={req}
                    client={clientMap.get(req.clientId)}
                    assignee={assigneeMap.get(req.assigneeId)}
                  />
                ))
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

