import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { PriorityBadge } from "@/components/inbox/priority-badge";
import { SlaChip } from "@/components/inbox/sla-chip";
import { formatRelative } from "@/lib/utils/time";
import type { Request, Client, Assignee } from "@/lib/types";

interface KanbanCardProps {
  request: Request;
  client: Client | undefined;
  assignee: Assignee | undefined;
}

function getInitials(name: string): string {
  return name
    .split(" ")
    .map((n) => n[0] ?? "")
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

export function KanbanCard({ request, client, assignee }: KanbanCardProps) {
  // TODO(phase2): wire drag-and-drop with dnd-kit
  return (
    <article
      draggable
      className="rounded-lg border bg-card p-3 shadow-card hover:shadow-soft-md transition cursor-grab active:cursor-grabbing"
    >
      {/* Top row: priority + SLA */}
      <div className="flex items-center justify-between gap-2">
        <PriorityBadge priority={request.priority} />
        <SlaChip slaDueAt={request.slaDueAt} />
      </div>

      {/* Title */}
      <p className="text-sm font-medium line-clamp-2 mt-2">{request.title}</p>

      {/* Raw message preview */}
      <p className="text-xs text-muted-foreground line-clamp-2 mt-1">
        {request.rawMessage}
      </p>

      {/* Bottom row: client + assignee */}
      <div className="flex items-center justify-between mt-3 gap-2">
        {/* Client */}
        {client ? (
          <div className="flex items-center gap-1.5 min-w-0">
            <Avatar size="sm">
              <AvatarImage src={client.avatarUrl} alt={client.name} />
              <AvatarFallback>{getInitials(client.name)}</AvatarFallback>
            </Avatar>
            <span className="text-xs text-muted-foreground truncate">
              {client.company}
            </span>
          </div>
        ) : (
          <span className="text-xs text-muted-foreground">Unknown client</span>
        )}

        {/* Assignee */}
        {assignee && (
          <Avatar size="sm">
            <AvatarImage src={assignee.avatarUrl} alt={assignee.name} />
            <AvatarFallback>{getInitials(assignee.name)}</AvatarFallback>
          </Avatar>
        )}
      </div>

      {/* Created */}
      <p className="text-xs text-muted-foreground mt-2">
        {formatRelative(request.createdAt)}
      </p>
    </article>
  );
}

