"use client";

import { useState } from "react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@/components/ui/select";
import type { Plan } from "@/lib/types";

interface NewClientDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface FormState {
  name: string;
  email: string;
  company: string;
  plan: Plan;
  mrr: string;
}

const DEFAULT_FORM: FormState = {
  name: "",
  email: "",
  company: "",
  plan: "starter",
  mrr: "",
};

export function NewClientDialog({ open, onOpenChange }: NewClientDialogProps) {
  const [form, setForm] = useState<FormState>(DEFAULT_FORM);

  function handleOpenChange(next: boolean) {
    if (!next) setForm(DEFAULT_FORM);
    onOpenChange(next);
  }

  function handleCreate() {
    toast.success("Client created (demo)", {
      description: "Connect Supabase to persist data.",
    });
    handleOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>New client</DialogTitle>
          <DialogDescription>
            Add a client to your workspace.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Contact Name */}
          <div className="space-y-1.5">
            <Label htmlFor="nc-name">Contact Name</Label>
            <Input
              id="nc-name"
              placeholder="Jane Smith"
              value={form.name}
              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
            />
          </div>

          {/* Email */}
          <div className="space-y-1.5">
            <Label htmlFor="nc-email">Email</Label>
            <Input
              id="nc-email"
              type="email"
              placeholder="jane@company.com"
              value={form.email}
              onChange={(e) =>
                setForm((f) => ({ ...f, email: e.target.value }))
              }
            />
          </div>

          {/* Company */}
          <div className="space-y-1.5">
            <Label htmlFor="nc-company">Company</Label>
            <Input
              id="nc-company"
              placeholder="Acme Inc"
              value={form.company}
              onChange={(e) =>
                setForm((f) => ({ ...f, company: e.target.value }))
              }
            />
          </div>

          {/* Plan */}
          <div className="space-y-1.5">
            <Label htmlFor="nc-plan">Plan</Label>
            <Select
              value={form.plan}
              onValueChange={(val) =>
                setForm((f) => ({ ...f, plan: (val ?? "starter") as Plan }))
              }
            >
              <SelectTrigger id="nc-plan">
                <SelectValue placeholder="Select plan" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="free">Free</SelectItem>
                <SelectItem value="starter">Starter</SelectItem>
                <SelectItem value="growth">Growth</SelectItem>
                <SelectItem value="scale">Scale</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* MRR */}
          <div className="space-y-1.5">
            <Label htmlFor="nc-mrr">MRR (USD)</Label>
            <Input
              id="nc-mrr"
              type="number"
              placeholder="149"
              value={form.mrr}
              onChange={(e) => setForm((f) => ({ ...f, mrr: e.target.value }))}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => handleOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleCreate}>Create client</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

