"use client";

import { useState } from "react";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@/components/ui/select";
import type { ServiceCategory } from "@/lib/types";

interface NewServiceDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface FormState {
  name: string;
  description: string;
  category: ServiceCategory;
  flatPrice: string;
  turnaroundDays: string;
}

const DEFAULT_FORM: FormState = {
  name: "",
  description: "",
  category: "design",
  flatPrice: "",
  turnaroundDays: "",
};

export function NewServiceDialog({
  open,
  onOpenChange,
}: NewServiceDialogProps) {
  const [form, setForm] = useState<FormState>(DEFAULT_FORM);

  function handleOpenChange(next: boolean) {
    if (!next) setForm(DEFAULT_FORM);
    onOpenChange(next);
  }

  function handleCreate() {
    toast.success("Service created (demo)", {
      description: "Connect Supabase to persist data.",
    });
    handleOpenChange(false);
  }

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>New service</DialogTitle>
          <DialogDescription>
            Add a productized service to your catalog.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-4">
          {/* Name */}
          <div className="space-y-2">
            <Label htmlFor="ns-name">Name</Label>
            <Input
              id="ns-name"
              placeholder="Webflow Landing Page"
              value={form.name}
              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
            />
          </div>

          {/* Description */}
          <div className="space-y-2">
            <Label htmlFor="ns-description">Description</Label>
            <Textarea
              id="ns-description"
              placeholder="Describe what's included in this service…"
              value={form.description}
              onChange={(e) =>
                setForm((f) => ({ ...f, description: e.target.value }))
              }
              className="resize-none"
              rows={3}
            />
          </div>

          {/* Category */}
          <div className="space-y-2">
            <Label htmlFor="ns-category">Category</Label>
            <Select
              value={form.category}
              onValueChange={(val) =>
                setForm((f) => ({
                  ...f,
                  category: (val ?? "design") as ServiceCategory,
                }))
              }
            >
              <SelectTrigger id="ns-category">
                <SelectValue placeholder="Select category" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="design">Design</SelectItem>
                <SelectItem value="development">Development</SelectItem>
                <SelectItem value="seo">SEO</SelectItem>
                <SelectItem value="content">Content</SelectItem>
                <SelectItem value="video">Video</SelectItem>
                <SelectItem value="ads">Ads</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Flat Price */}
          <div className="space-y-2">
            <Label htmlFor="ns-price">Flat Price (USD / mo)</Label>
            <Input
              id="ns-price"
              type="number"
              placeholder="299"
              value={form.flatPrice}
              onChange={(e) =>
                setForm((f) => ({ ...f, flatPrice: e.target.value }))
              }
            />
          </div>

          {/* Turnaround Days */}
          <div className="space-y-2">
            <Label htmlFor="ns-turnaround">Turnaround Days</Label>
            <Input
              id="ns-turnaround"
              type="number"
              placeholder="3"
              value={form.turnaroundDays}
              onChange={(e) =>
                setForm((f) => ({ ...f, turnaroundDays: e.target.value }))
              }
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => handleOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleCreate}>Create service</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

